// 1. Obter a lista de clientes recebida pelo nó Webhook
const webhookBody = $('Webhook Clientes').first().json.body;
const clientes = webhookBody.clientes || [];

// 2. Obter o conteúdo do CSV baixado pelo nó HTTP Request
const csvRaw = $input.first().json.data || $input.first().json;
const csvText = typeof csvRaw === 'string' ? csvRaw : JSON.stringify(csvRaw);

// 3. Processar as linhas do CSV de investimentos
const linhas = csvText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
const investimentos = [];

for (let i = 1; i < linhas.length; i++) {
  const colunas = linhas[i].split(',');
  if (colunas.length >= 4) {
    investimentos.push({
      perfil: colunas[0].trim(),
      produto: colunas[1].trim(),
      minimo: parseFloat(colunas[2].trim()) || 0,
      rentabilidade: colunas[3].trim()
    });
  }
}

// 4. Cruzar clientes com investimentos e gerar mensagens personalizadas
const clientesComRecomendacao = clientes.map(cliente => {
  const opcoesPerfil = investimentos.filter(
    inv => inv.perfil.toLowerCase() === (cliente.perfil || '').toLowerCase()
  );

  const resumoOpcoes = opcoesPerfil.map(
    op => `• ${op.produto} (Aplicação mín: R$ ${op.minimo}, Rentabilidade: ${op.rentabilidade})`
  ).join('\n');

  const mensagem = `Olá, ${cliente.nome}!\n\n` +
    `Identificamos que seu perfil de investidor é ${cliente.perfil} e seu saldo disponível é ${cliente.saldo}.\n` +
    `Selecionamos as seguintes oportunidades ideais para você:\n${resumoOpcoes}\n\n` +
    `Fale com seu consultor para iniciar os aportes!`;

  return {
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    perfil: cliente.perfil,
    investimentos_sugeridos: opcoesPerfil,
    mensagem_personalizada: mensagem
  };
});

return clientesComRecomendacao.map(item => ({ json: item }));

